import{_ as i}from"./chunks/image12.BRgDBKom.js";import{_ as a,o as n,c as s,am as t,j as o}from"./chunks/framework.CenUaW7a.js";const r="/projects/AiMechaM1/en/advanced-kit/assets/video1.UAHTF0BY.mp4",l="/projects/AiMechaM1/en/advanced-kit/assets/image2.C23wTIsb.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.D_8dCgqe.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image4.D9uFUl6Z.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image5.ythTOfgS.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image6.Dgh6ojLz.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image7.oJzgytE_.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image8.sUlYpGuE.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image9.BzUdKAd_.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image10.CxkbxVhU.png",v="/projects/AiMechaM1/en/advanced-kit/assets/image12.CAQ3AuIT.png",b="/projects/AiMechaM1/en/advanced-kit/assets/image13.DjsvpbiA.png",y="/projects/AiMechaM1/en/advanced-kit/assets/image14.SaU6S3bQ.png",I=JSON.parse('{"title":"3.29 Lesson 29: Introduction and Application of Large Vision Models","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.29 Lesson 29 Introduction and Application of Large Vision Models.md","filePath":"docs/3. Course materials/3.29 Lesson 29 Introduction and Application of Large Vision Models.md"}'),w={name:"docs/3. Course materials/3.29 Lesson 29 Introduction and Application of Large Vision Models.md"};function _(x,e,k,q,A,C){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-29-lesson-29-introduction-and-application-of-large-vision-models" tabindex="-1">3.29 Lesson 29: Introduction and Application of Large Vision Models <a class="header-anchor" href="#_3-29-lesson-29-introduction-and-application-of-large-vision-models" aria-label="Permalink to &quot;3.29 Lesson 29: Introduction and Application of Large Vision Models&quot;">​</a></h1><h2 id="_3-29-1-lesson-introduction" tabindex="-1">3.29.1 Lesson Introduction <a class="header-anchor" href="#_3-29-1-lesson-introduction" aria-label="Permalink to &quot;3.29.1 Lesson Introduction&quot;">​</a></h2><p>This lesson focuses on large vision models, exploring the paradigm shift from &quot;specialized recognition&quot; to &quot;general visual comprehension&quot;. Inspired by multidimensional human visual perception, the curriculum introduces the capability of &quot;comprehending everything in sight&quot;. Core concepts cover the operating principles of large vision models, contrasting specialized traditional computer vision with generalized cross-modal comprehension, and illustrating how the Contrastive Language-Image Pre-training model known as CLIP bridges semantic and pixel spaces. Four major application scenarios spanning security, healthcare, autonomous driving, and retail are examined. Practical exercises feature two progressive tasks: using voice commands to invoke the vision model for broadcasting object features, and linking face detection with robotic arm swaying. Upgrading from specialized detection to general vision lays the foundation for deep perception and embodied intelligence.</p><h2 id="_3-29-2-learning-objectives" tabindex="-1">3.29.2 Learning Objectives <a class="header-anchor" href="#_3-29-2-learning-objectives" aria-label="Permalink to &quot;3.29.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the core definition and technical principles of large vision models. Master the fundamental differences between traditional computer vision and large vision models. Learn the image-text contrastive learning approach and zero-shot recognition capabilities of the CLIP model.</p><p><strong>2.</strong> Implement online large-model-based visual recognition calls through programming. Trigger vision model recognition and voice announcements via voice commands, and develop control programs that link visual recognition results to robotic arm movements.</p><p><strong>3.</strong> Establish a cross-modal understanding mindset by recognizing the semantic associations between images and natural language. Develop an awareness of the technological evolution from &quot;specialized AI&quot; to &quot;general AI&quot;, and enhance system design capabilities for multimodal fusion.</p><p><strong>4.</strong> Relate these concepts to industry scenarios, such as smart security, medical imaging, autonomous driving, and smart retail, to understand the transformative value of large vision models across industries and spark interest in exploring general vision AI and multimodal large models.</p><h2 id="_3-29-3-preparation" tabindex="-1">3.29.3 Preparation <a class="header-anchor" href="#_3-29-3-preparation" aria-label="Permalink to &quot;3.29.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Core Concept Description</strong>:</p><ul><li><p><strong>Traditional Computer Vision or CV</strong>: Task-specific &quot;specialist&quot; models where a single model performs only one designated task and recognizes only pre-trained categories—for instance, a facial recognition model only identifies faces, and an object detection model only detects 80 preset object classes.</p></li><li><p><strong>Large Vision Models</strong>: General-purpose vision models pre-trained on massive image-text datasets, possessing strong generalization and cross-modal comprehension capabilities to link visual features with linguistic concepts and achieve instant comprehension upon sight.</p></li><li><p><strong>Zero-Shot Recognition</strong>: The capability of a model to directly identify novel objects without prior training samples of those classes, relying on semantic comprehension rather than rote memorization.</p></li><li><p><strong>Cross-Modal Understanding</strong>: The capability of AI to simultaneously comprehend visual and linguistic modalities while establishing semantic associations between them.</p></li></ul><p><strong>Four Real-World Application Scenarios</strong>:</p><ul><li><p><strong>Smart Security</strong>: Surveillance cameras not only detect human presence, but also analyze whether &quot;a person is running&quot; or &quot;exhibiting violent or abnormal behavior&quot;, upgrading from basic presence detection to behavioral comprehension.</p></li><li><p><strong>Medical Diagnosis</strong>: Medical imaging AI surpasses senior physicians in pulmonary nodule detection rates, while large models support open-ended diagnostic consultations to provide auxiliary assessments, upgrading from lesion detection to &quot;medical record analysis&quot; and &quot;clinical recommendations&quot;.</p></li><li><p><strong>Autonomous Driving</strong>: Systems detect fine-grained road details in real time, such as locating damaged road markings, and interpret pedestrian intentions in complex traffic, upgrading from &quot;object detection&quot; to &quot;scene comprehension&quot;.</p></li><li><p><strong>Smart Retail</strong>: Uploading a product photo allows the system to rapidly match exact inventory items via semantic search, upgrading from &quot;barcode lookup&quot; to &quot;image-based retrieval&quot;.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller via UART serial communication.</p></li><li><p>Connect the camera to the dedicated camera port on the K230 screen module.</p></li><li><p>Connect the three bus servos in series to bus ports S1 or S2.</p></li></ul><p><strong>Large Vision Models vs. Traditional CV Comparison</strong>:</p><ul><li><p>Traditional CV: One model per task, recognizes only pre-trained categories, outputs structured data such as bounding boxes, class labels, and coordinates, and requires retraining for new tasks.</p></li><li><p>Large Vision Models: One model for multiple tasks, performs zero-shot recognition on unseen categories, outputs natural language descriptions, and offers strong general capabilities supporting open-ended visual question answering.</p></li></ul><h2 id="_3-29-4-practical-implementation" tabindex="-1">3.29.4 Practical Implementation <a class="header-anchor" href="#_3-29-4-practical-implementation" aria-label="Permalink to &quot;3.29.4 Practical Implementation&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a voice-triggered large vision model recognition and actuation system centered around a multimodal perception, comprehension, and response closed loop. The K230 camera and microphone perform dual-channel capture and upload data via Wi-Fi to the cloud multimodal large model. After cloud ASR transcribes the audio into text and the large model interprets the command intent, the model deeply analyzes the visual frame to output semantic descriptions including object names, quantities, and states. The intent-driven decision layer invokes the robotic arm MCP tool to output target coordinates and durations when motion is required, or generates speech when broadcasting is requested. The execution layer synthesizes speech to read results aloud and drives servos to sway, salute, or grasp with the robotic arm. Forming a complete chain from voice trigger → visual perception → large model comprehension → voice or physical response, the system demonstrates how multimodal AI simultaneously sees, hears, speaks, and acts.</p>',24),o("p",null,[o("video",{controls:"",playsinline:"",preload:"metadata",src:r})],-1),t('<p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Module initialization</td><td style="text-align:center;"><img loading="lazy" height="65" width="328" src="'+l+'" class="common_img" style="width:240px;aspect-ratio:328 / 65;"></td><td style="text-align:left;">Configures UART serial communication for the K230 module to establish a connection with the controller.</td></tr><tr><td style="text-align:center;">Network configuration</td><td style="text-align:center;"><img loading="lazy" height="72" width="519" src="'+c+'" class="common_img" style="width:360px;aspect-ratio:519 / 72;"></td><td style="text-align:left;">Configures the Wi-Fi network to connect to cloud multimodal large model services.</td></tr><tr><td style="text-align:center;">Mode configuration</td><td style="text-align:center;"><img loading="lazy" height="70" width="453" src="'+d+'" class="common_img" style="width:300px;aspect-ratio:453 / 70;"></td><td style="text-align:left;">Switches to the online large model mode to enable vision and speech multimodal capabilities.</td></tr><tr><td style="text-align:center;">MCP configuration</td><td style="text-align:center;"><img loading="lazy" height="69" width="379" src="'+p+'" class="common_img" style="width:260px;aspect-ratio:379 / 69;"></td><td style="text-align:left;">Loads the default MCP tool set, including visual recognition and robotic arm control tools.</td></tr><tr><td style="text-align:center;">Detection control</td><td style="text-align:center;"><img loading="lazy" height="68" width="233" src="'+g+'" class="common_img" style="width:170px;aspect-ratio:233 / 68;"></td><td style="text-align:left;">Starts the large model multimodal interaction engine to monitor voice commands and capture camera frames.</td></tr><tr><td style="text-align:center;">Data synchronization</td><td style="text-align:center;"><img loading="lazy" height="68" width="321" src="'+m+'" class="common_img" style="width:210px;aspect-ratio:321 / 68;"></td><td style="text-align:left;">Synchronizes the latest large model recognition results and tool-calling commands.</td></tr><tr><td style="text-align:center;">Result detection</td><td style="text-align:center;"><img loading="lazy" height="55" width="250" src="'+u+'" class="common_img" style="width:210px;aspect-ratio:250 / 55;"></td><td style="text-align:left;">Determines whether the large model has returned new recognition results or tool calls.</td></tr><tr><td style="text-align:center;">Result retrieval</td><td style="text-align:center;"><img loading="lazy" height="48" width="282" src="'+h+'" class="common_img" style="width:210px;aspect-ratio:282 / 48;"></td><td style="text-align:left;">Reads the complete recognition results.</td></tr><tr><td style="text-align:center;">Tool evaluation</td><td style="text-align:center;"><img loading="lazy" height="38" width="554" src="'+f+'" class="common_img" style="width:400px;aspect-ratio:554 / 38;"></td><td style="text-align:left;">Evaluates whether the large model has invoked the robotic arm motion control tool.</td></tr><tr><td style="text-align:center;">Result feedback</td><td style="text-align:center;"><img loading="lazy" height="47" width="389" src="'+v+'" class="common_img" style="width:400px;aspect-ratio:389 / 47;"></td><td style="text-align:left;">Sends tool execution success feedback to the large model to complete the invocation closed loop.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Recognizing Objects and Intelligently Broadcasting Information</strong></p><ul><li><p>Initialization settings: Upon startup, wait 6 seconds and play note B5 for a 1/8 beat as the startup prompt tone. Initialize port A, configure the Wi-Fi SSID and password, load the default MCP configuration, set the operating mode to online large model, initialize the linkage robotic arm, and play note B6 for a 1/8 beat as the readiness prompt tone.</p></li><li><p>Voice trigger: Speak the wake word <code>Hello Hiwonder</code>, followed by a voice command such as <code>Recognize the objects and broadcast relevant information</code> or <code>See what is in front</code>.</p></li><li><p>Cloud processing: Upon receiving the command, the large model triggers the camera to capture an image, analyzes the scene using the large vision model, and generates a natural language description such as <code>Detected three types of fruit ahead: a peach, an apple, and grapes</code>.</p></li><li><p>Voice broadcast: Text-to-speech synthesis converts the generated description into audio played back through the K230 module, &quot;describing exactly what the camera sees&quot;.</p></li><li><p>Key takeaway: Unlike traditional object detection that only outputs class labels, a large vision model provides rich semantic descriptions covering quantities, colors, relative positions, and object states.</p></li></ul><img loading="lazy" height="288" width="450" src="'+b+'" class="common_img" style="width:600px;aspect-ratio:450 / 288;"><p><strong>Task 2: Face Detection Linked with Robotic Arm Swaying</strong></p><ul><li><p>Main program framework: Uses the exact same initialization sequence and main loop structure as Task 1.</p></li><li><p>Result retrieval: If <code>Does result exist?</code> returns true, store the retrieved recognition result in the AIresult variable.</p></li><li><p>Robotic arm motion evaluation: If AIresult contains the default MCP tool name for robotic arm motion, command the robotic arm end effector to move to the forward-backward Y-axis coordinate in millimeters and vertical Z-axis coordinate in millimeters extracted from AIresult over the specified duration in milliseconds.</p></li><li><p>Gripper control evaluation: If AIresult contains the default MCP tool name for the mechanical gripper, set bus servo ID 1 to the target angle in degrees over the duration in milliseconds extracted from AIresult.</p></li><li><p>Send feedback: Send a response result with dictionary key <code>result</code> and value <code>ok</code> after each tool execution completes.</p></li><li><p>Voice command examples: <code>Hello Hiwonder, sway the robotic arm if someone is ahead</code>, or <code>salute upon detecting a face</code>.</p></li><li><p>Execution outcome: When the camera detects a human face, the robotic arm automatically sways up and down or performs a saluting gesture, directly translating visual perception into physical action.</p></li></ul><img loading="lazy" height="305" width="1245" src="'+y+'" class="common_img" style="width:800px;aspect-ratio:1245 / 305;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Variable caching: Read all tool parameters from the AIresult variable to guarantee data consistency throughout each processing cycle.</p></li><li><p>Voice-driven execution: Trigger all visual functions via natural language commands without hard-coding fixed routines, executing whatever task is requested by voice.</p></li><li><p>Large model parsing: The large model automatically interprets command intent to determine whether to merely broadcast results or control hardware, eliminating the need to manually manage low-level technical details.</p></li><li><p>Natural language output: Visual recognition outputs fluent natural language descriptions rather than rigid structured data, creating a much more natural human-robot interaction experience.</p></li></ul><p><strong>Typical Experience Phrases</strong></p><ul><li><p><code>Hello Hiwonder, see what fruits are ahead</code></p></li><li><p><code>Hello Hiwonder, identify what this object is</code></p></li><li><p><code>Hello Hiwonder, nod upon detecting a face</code></p></li><li><p><code>Hello Hiwonder, check the fruits ahead and recommend which one is best when feeling sick.</code></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Visual Model Application</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button on the top toolbar of the software and select the COM port corresponding to CH340 from the dropdown list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to compile and download the program to the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+i+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-29-5-expansion-and-advancement" tabindex="-1">3.29.5 Expansion and Advancement <a class="header-anchor" href="#_3-29-5-expansion-and-advancement" aria-label="Permalink to &quot;3.29.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Intelligent Tour Guide Robot</strong></p><p>Design a visual tour guide robot task: program the car to move slowly through a classroom, automatically identifying objects at each stop and introducing them via voice broadcast. For instance, upon detecting a blackboard, broadcast &quot;This is a blackboard, used for writing instructional content&quot;, and upon detecting a desk, broadcast &quot;This is a desk, designed for reading and studying&quot;. Explore the scene description capabilities of large vision models to build an intelligent tour guide robot that &quot;narrates while navigating&quot;, demonstrating how general vision empowers autonomous guided tours.</p><p><strong>Expansion Project 2: Interactive Visual Question Answering System</strong></p><p>Implement open-ended visual question answering: show any object to the camera and ask voice questions such as &quot;What color is this?&quot;, &quot;How many of these are there?&quot;, or &quot;What is this used for?&quot;, prompting the large model to analyze the visual frame and provide targeted answers. Explore multi-turn dialogue and reasoning in large vision models, upgrading from &quot;recognizing objects&quot; to &quot;answering any questions about the image&quot;. Understand the Visual Question Answering, or VQA, capabilities of vision-language models, and experience the power of knowledge fusion in multimodal large models.</p><h2 id="_3-29-6-q-a" tabindex="-1">3.29.6 Q&amp;A <a class="header-anchor" href="#_3-29-6-q-a" aria-label="Permalink to &quot;3.29.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the most prominent advantage of large vision models compared to traditional vision models?</strong></p><p>A. Recognizing traffic lights.<br> B. Recognizing human faces.<br> C. Recognizing objects ahead and announcing their detailed information.<br> D. Recognizing animals.</p><p><strong>Answer: C</strong></p><p><strong>Q2: To make the robot perform a waving motion with its robotic arm upon detecting a person ahead, what additional programming commands must be included besides visual recognition to drive the robotic arm?</strong></p><p><strong>Answer</strong>: Include commands that <strong>control the motion of each robotic arm joint</strong> so the robotic arm follows a waving trajectory.</p><h2 id="_3-29-7-technical-support-and-discussion" tabindex="-1">3.29.7 Technical Support and Discussion <a class="header-anchor" href="#_3-29-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.29.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',29)])])}const z=a(w,[["render",_]]);export{I as __pageData,z as default};
